SELECT id,batch_id,source_channel FROM t_import_batch WHERE batch_status='PROCESSING' AND (next_retry_at IS NULL OR next_retry_at<=CURRENT_TIMESTAMP(3)) AND (lease_expires_at IS NULL OR lease_expires_at<CURRENT_TIMESTAMP(3))
AND source_channel NOT IN #{channel}
ORDER BY created_at LIMIT 1 FOR UPDATE SKIP LOCKED
